options(survey.lonely.psu='adjust');r<-'./TB_metabolome_exposome_20261115_2130';o<-'./系统复审与优化_20261116';.libPaths(c(file.path(r,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));suppressPackageStartupMessages(library(survey));suppressPackageStartupMessages(library(splines));a<-as.data.frame(readRDS(file.path(r,'analysis_MWAS_ExWAS/derived/analysis_2011-2012.rds')));w<-as.data.frame(readRDS(file.path(r,'output/2011-2012/NHANES_2011-2012_full_population_wide_TBflags.rds')));w<-w[match(a$SEQN,w$SEQN),];stopifnot(all(w$SEQN==a$SEQN));a$group<-ifelse(!is.na(a$QFT)&!is.na(a$TST10),paste0('Q',a$QFT,'T',a$TST10),NA);a$y<-ifelse(a$group=='Q1T0',1,ifelse(a$group=='Q0T1',0,NA));a$adult<-a$age>=20;a$birth<-factor(a$foreign_born,levels=c(0,1));a$smoking<-factor(a$smoking);a$BMI<-as.numeric(w$BMXBMI);a$vitD<-as.numeric(w$LBXVIDMS);a$albumin<-as.numeric(w$LBXSAL);a$weight_now<-ifelse(w$WHD020%in%c(7777,9999,777,999),NA,w$WHD020);a$weight_last<-ifelse(w$WHD050%in%c(7777,9999,777,999),NA,w$WHD050);a$loss_lb<-a$weight_last-a$weight_now;a$unintent<-ifelse(is.na(a$loss_lb),NA,ifelse(a$loss_lb<10,0,ifelse(w$WHQ060==2,1,ifelse(w$WHQ060==1,0,NA))));a$risk<-ifelse(!is.na(a$BMI)&!is.na(a$unintent),as.integer(a$BMI<18.5|a$unintent==1),NA);a$logcd<-ifelse(a$LBXBCD>0,log2(a$LBXBCD),NA);cv<-c('age','sex_male','race','educ','PIR','birth','smoking');eligible<-is.finite(a$WTMEC2YR)&a$WTMEC2YR>0&!is.na(a$SDMVSTRA)&!is.na(a$SDMVPSU);d<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTMEC2YR,nest=TRUE,data=a[eligible,]);rows<-list();for(g in c('Q0T0','Q1T0','Q0T1','Q1T1')){s<-subset(d,adult&group==g&!is.na(risk));v<-svymean(~risk,s);ci<-confint(v,df=degf(s));rows[[length(rows)+1]]<-data.frame(group=g,n=nrow(s$variables),risk_n=sum(s$variables$risk),underweight_n=sum(s$variables$BMI<18.5),unintentional_10lb_n=sum(s$variables$unintent),weighted_proportion=unname(coef(v)),low=max(0,ci[1]),high=min(1,ci[2]),df=degf(s))};write.csv(do.call(rbind,rows),file.path(o,'数据表/07_低BMI或非意愿体重下降.csv'),row.names=FALSE)
res<-list();for(x in c('LBXBPB','LBXBCD','LBXTHG'))for(m in c('BMI','vitD','albumin')){a$.x<-ifelse(a[[x]]>0,log2(a[[x]]),NA);mask<-a$adult&!is.na(a$y)&complete.cases(a[,c('.x',m,cv)]);mask[is.na(mask)]<-FALSE;av<-mean(a[[m]][mask]);sdv<-sd(a[[m]][mask]);a$.m<-(a[[m]]-av)/sdv;a$.domain<-mask;d<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTMEC2YR,nest=TRUE,data=a[eligible,]);d<-subset(d,.domain);fit<-svyglm(as.formula(paste('y~.x*.m+',paste(cv,collapse='+'))),d,family=quasibinomial());b<-coef(fit)['.x:.m'];se<-sqrt(diag(vcov(fit)))['.x:.m'];df<-fit$df.residual;res[[length(res)+1]]<-data.frame(exposure=x,nutrition=m,n=nrow(d$variables),cases=sum(d$variables$y),design_df=degf(d),residual_df=df,OR_ratio=unname(exp(b)),low=unname(exp(b-qt(.975,df)*se)),high=unname(exp(b+qt(.975,df)*se)),p=unname(2*pt(-abs(b/se),df)))};z<-do.call(rbind,res);z$q_BH<-p.adjust(z$p,'BH');write.csv(z,file.path(o,'数据表/08_营养交互残余自由度重算.csv'),row.names=FALSE)
a$.domain<-a$adult&!is.na(a$y)&complete.cases(a[,c('logcd',cv)]);a$.domain[is.na(a$.domain)]<-FALSE;d<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTMEC2YR,nest=TRUE,data=a[eligible,]);d<-subset(d,.domain);fit<-svyglm(y~ns(logcd,df=3)+age+sex_male+race+educ+PIR+birth+smoking,d,family=quasibinomial());sink(file.path(o,'数据表/09_血镉非线性审计.txt'));print(summary(fit));cat('\nSpline overall Wald test (not a nonlinearity-specific test):\n');print(regTermTest(fit,~ns(logcd,df=3)));cat('\nThree spline terms use much of available design df; exploratory only.\n');sink();cat('nutritional and nonlinear analyses complete\n');print(do.call(rbind,rows));print(z)
